/* =============================================================
   Nourished — Shared chrome: header, mobile nav, cart drawer,
   footer. Injected on every page; wires global interactions.
   ============================================================= */
(() => {
  const page = (location.pathname.split('/').pop() || 'index.html');
  const NAV = [
    ['shop.html', 'Shop'],
    ['build-a-box.html', 'Build a Box'],
    ['quiz.html', 'Find Your Flavour'],
    ['subscribe.html', 'Subscribe &amp; Save'],
    ['about.html', 'About'],
    ['stockists.html', 'Stockists'],
    ['contact.html', 'Contact']
  ];
  const cur = (href) => page === href ? 'aria-current="page"' : '';
  const navLinks = NAV.map(([h, l]) => `<a href="${h}" ${cur(h)}>${l}</a>`).join('');

  const cartIcon = `
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>`;

  /* ---- Header ---- */
  const header = `
    <div class="announce">Free delivery on orders over <strong>R1000</strong> · No added sugar, all the fun 🍬</div>
    <header class="site-header">
      <div class="container nav">
        <a class="nav__logo" href="index.html" aria-label="Nourished home">
          <img src="data:image/png;base64," alt="Nourished — Natural & Fun Snacks" width="641" height="200">
        </a>
        <nav class="nav__links" aria-label="Primary">${navLinks}</nav>
        <div class="nav__actions">
          <button class="icon-btn" id="sound-toggle" aria-pressed="false" aria-label="Toggle sound effects" title="Sound effects">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H2v6h4l5 4z"/><path class="snd-on" d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07" style="display:none"/><line class="snd-off" x1="22" y1="9" x2="16" y2="15"/><line class="snd-off" x1="16" y1="9" x2="22" y2="15"/></svg>
          </button>
          <button class="icon-btn" id="cart-open" data-cart-target aria-label="Open cart">
            ${cartIcon}<span class="cart-count" data-cart-count>0</span>
          </button>
          <button class="icon-btn nav__toggle" id="nav-open" aria-label="Open menu" aria-expanded="false">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
          </button>
        </div>
      </div>
    </header>`;

  /* ---- Mobile nav ---- */
  const mobileNav = `
    <div class="mobile-nav" id="mobile-nav" aria-hidden="true">
      <div class="mobile-nav__head">
        <img src="data:image/png;base64," alt="Nourished" height="42">
        <button class="icon-btn" id="nav-close" aria-label="Close menu">✕</button>
      </div>
      <nav aria-label="Mobile">${NAV.map(([h, l]) => `<a href="${h}" ${cur(h)}>${l}</a>`).join('')}</nav>
    </div>`;

  /* ---- Cart drawer ---- */
  const drawer = `
    <div class="overlay" id="overlay"></div>
    <aside class="cart-drawer" id="cart-drawer" role="dialog" aria-label="Shopping cart" aria-hidden="true">
      <div class="cart-drawer__head">
        <h2>Your bag</h2>
        <button class="icon-btn" id="cart-close" aria-label="Close cart">✕</button>
      </div>
      <div class="ship-bar">
        <div class="ship-bar__msg" data-ship-msg></div>
        <div class="ship-bar__track"><div class="ship-bar__fill" data-ship-fill></div></div>
      </div>
      <div class="cart-items" id="cart-items"></div>
      <div class="cart-drawer__foot">
        <div class="cart-row" data-saved-row style="display:none;color:var(--leaf)"><span>Subscription savings</span><span data-sum-saved>R0</span></div>
        <div class="cart-row"><span>Subtotal</span><span data-sum-subtotal>R0</span></div>
        <div class="cart-row"><span>Delivery</span><span data-sum-shipping>R0</span></div>
        <div class="cart-row cart-row--total"><span>Total</span><span data-sum-total>R0</span></div>
        <button class="btn btn--lg btn--block" id="checkout-btn">Checkout</button>
        <p class="muted center" style="font-size:.78rem;margin-top:.6rem">Prototype — checkout is for demo only</p>
      </div>
    </aside>`;

  /* ---- Footer ---- */
  const year = document.documentElement.getAttribute('data-year') || '2026';
  const footer = `
    <footer class="site-footer">
      <div class="container">
        <div class="footer-grid">
          <div class="footer-brand">
            <img src="data:image/png;base64," alt="Nourished" height="54" style="filter:brightness(0) invert(1);margin-bottom:1rem">
            <p>Natural and fun snacks for South Africa. Better-for-you sweets with no added sugar — proudly bringing FUNDAY Natural Sweets to SA.</p>
            <form class="newsletter" id="newsletter-form">
              <input type="email" name="email" placeholder="Join the fam — your email" aria-label="Email for newsletter" required>
              <button class="btn" type="submit">Join</button>
            </form>
            <p class="muted" id="newsletter-msg" style="font-size:.8rem;margin-top:.5rem;color:var(--citrus);display:none">🎉 You're in! Welcome to the Nourished fam.</p>
          </div>
          <div><h4>Shop</h4><ul>
            <li><a href="shop.html">All sweets</a></li>
            <li><a href="build-a-box.html">Build a Box</a></li>
            <li><a href="quiz.html">Find Your Flavour</a></li>
            <li><a href="subscribe.html">Subscribe &amp; Save</a></li>
          </ul></div>
          <div><h4>Learn</h4><ul>
            <li><a href="about.html">About the brand</a></li>
            <li><a href="stockists.html">Where to buy</a></li>
            <li><a href="contact.html">Contact us</a></li>
          </ul></div>
          <div><h4>Say hi</h4><ul>
            <li><a href="mailto:${STORE.email}">${STORE.email}</a></li>
            <li><a href="contact.html">Wholesale &amp; stockists</a></li>
            <li style="display:flex;gap:.8rem;margin-top:.4rem">
              <a href="${STORE.social.instagram}" aria-label="Instagram">Instagram</a>
              <a href="${STORE.social.tiktok}" aria-label="TikTok">TikTok</a>
            </li>
          </ul></div>
        </div>
        <div class="footer-bottom">
          <span>© ${year} Nourished. All rights reserved.</span>
          <span>No added sugar · Natural colours &amp; flavours · Gluten free</span>
        </div>
      </div>
    </footer>`;

  /* ---- Mount ---- */
  const hSlot = document.getElementById('header-slot');
  const fSlot = document.getElementById('footer-slot');
  if (hSlot) hSlot.innerHTML = header + mobileNav;
  if (fSlot) fSlot.innerHTML = footer;
  document.body.insertAdjacentHTML('beforeend', drawer);

  /* ---- Wire interactions ---- */
  const $ = s => document.querySelector(s);
  $('#cart-open')?.addEventListener('click', () => Cart.open());
  $('#cart-close')?.addEventListener('click', () => Cart.close());
  $('#overlay')?.addEventListener('click', () => Cart.close());
  $('#checkout-btn')?.addEventListener('click', () => {
    if (Cart.totals().empty) return;
    FX.celebrate();
    alert('Thanks! This is a prototype — in the live store this goes to secure Shopify checkout.');
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { Cart.close(); closeNav(); } });

  const mnav = $('#mobile-nav');
  function openNav() { mnav?.classList.add('is-open'); mnav?.setAttribute('aria-hidden', 'false'); $('#nav-open')?.setAttribute('aria-expanded', 'true'); }
  function closeNav() { mnav?.classList.remove('is-open'); mnav?.setAttribute('aria-hidden', 'true'); $('#nav-open')?.setAttribute('aria-expanded', 'false'); }
  $('#nav-open')?.addEventListener('click', openNav);
  $('#nav-close')?.addEventListener('click', closeNav);

  // sound toggle
  $('#sound-toggle')?.addEventListener('click', e => {
    const on = FX.toggleSound();
    const btn = e.currentTarget;
    btn.setAttribute('aria-pressed', String(on));
    btn.querySelectorAll('.snd-off').forEach(n => n.style.display = on ? 'none' : '');
    btn.querySelectorAll('.snd-on').forEach(n => n.style.display = on ? '' : 'none');
    if (on) FX.pop(660);
  });

  // newsletter (demo)
  $('#newsletter-form')?.addEventListener('submit', e => {
    e.preventDefault();
    const msg = $('#newsletter-msg'); if (msg) msg.style.display = 'block';
    e.target.reset(); FX.celebrate({ particleCount: 50 });
  });

  // initial render + reveals
  Cart.render();
  FX.initReveals();
  FX.initTilt();
})();
